<?php
require 'bootstrap.php';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();
 try{
    $registered=isset($_POST['registered']);$taxId=post('tax_id');$name=post('legal_name');$address=post('legal_address');$branch=post('branch');$mode=post('price_mode');
    if(strlen($taxId)>13)throw new RuntimeException('เลขผู้เสียภาษีต้องไม่เกิน 13 หลัก');if(!in_array($mode,['inclusive','exclusive'],true)||mb_strlen($name)>190||mb_strlen($address)>3000||mb_strlen($branch)>80)throw new RuntimeException('ข้อมูลผู้ขายหรือวิธีคิดภาษีไม่ถูกต้อง');
    if($registered&&(!preg_match('/^[0-9]{13}$/D',$taxId)||$name===''||$address===''||post('legal_confirm')!=='1'))throw new RuntimeException('ต้องกรอกข้อมูลผู้ประกอบการจริงและยืนยันจด VAT ก่อนเปิด');
    $from=post('starts_on');$until=post('ends_on');$rate=commerce_money_input(post('rate')?:'0');if($rate>2500)throw new RuntimeException('อัตราภาษีเกินช่วงที่รองรับ');
    if($registered){foreach([$from,$until] as $date){$d=DateTimeImmutable::createFromFormat('!Y-m-d',$date);if(!$d||$d->format('Y-m-d')!==$date)throw new RuntimeException('วันที่อัตราภาษีไม่ถูกต้อง');}if($from>$until||date('Y-m-d')<$from||date('Y-m-d')>$until)throw new RuntimeException('ตั้งช่วงอัตราให้ครอบคลุมวันนี้ก่อนเปิด VAT');}
    db()->beginTransaction();q('SELECT id FROM tax_settings WHERE id=1 FOR UPDATE');
    q('UPDATE tax_settings SET registered=?,tax_id=?,legal_name=?,legal_address=?,branch=?,price_mode=?,shipping_taxable=?,invoice_enabled=?,confirmed_by=?,confirmed_at=? WHERE id=1',[$registered?1:0,$taxId,$name,$address,$branch,$mode,isset($_POST['shipping_taxable'])?1:0,$registered&&isset($_POST['invoice_enabled'])?1:0,$registered?$admin['id']:null,$registered?date('Y-m-d H:i:s'):null]);
    if($registered){q('UPDATE tax_rates SET active=0');q('INSERT INTO tax_rates(rate_bps,starts_on,ends_on,active,updated_by) VALUES (?,?,?,1,?)',[$rate,$from,$until,$admin['id']]);}
    db()->commit();flash('บันทึกการตั้งค่าภาษีแล้ว คำสั่งซื้อเดิมไม่เปลี่ยน');go('admin/taxes.php');
 }catch(Throwable $ex){if(db()->inTransaction())db()->rollBack();$error=$ex instanceof PDOException?'บันทึกการตั้งค่าภาษีไม่สำเร็จ':$ex->getMessage();}
}
$settings=tax_settings();$current=q('SELECT * FROM tax_rates WHERE active=1 ORDER BY id DESC LIMIT 1')->fetch()?:[];$value=static fn($key,$default='')=>$_SERVER['REQUEST_METHOD']==='POST'?post($key):($settings[$key]??$default);admin_header('ตั้งค่าภาษีและเอกสาร');
?>
<div class="notice">ค่าเริ่มต้นไม่จด VAT และไม่ออกใบกำกับภาษี ใส่ข้อมูลจริงและให้ผู้รับผิดชอบบัญชียืนยันอัตรา การยกเว้นสินค้า ค่าจัดส่ง และส่วนลดก่อนเปิดใช้งาน ระบบไม่ยืนยันสิทธิ์การจดทะเบียนแทนกรมสรรพากร</div><?php if($error): ?><p class="error"><?=e(t($error))?></p><?php endif ?>
<form method="post" class="panel commerce-admin-form"><?=csrf()?><label class="checkbox"><input type="checkbox" name="registered" <?=($_SERVER['REQUEST_METHOD']==='POST'?isset($_POST['registered']):$settings['registered'])?'checked':''?>> ร้านจดทะเบียน VAT แล้ว</label><?php field('tax_id','เลขผู้เสียภาษีจริง 13 หลัก','text',$value('tax_id'),false);field('legal_name','ชื่อผู้ประกอบการตามทะเบียน','text',$value('legal_name'),false); ?><label>ที่อยู่ผู้ประกอบการ<textarea name="legal_address" maxlength="3000"><?=e($value('legal_address'))?></textarea></label><?php field('branch','สาขา','text',$value('branch','สำนักงานใหญ่')); ?><label>ราคาสินค้า<select name="price_mode"><option value="inclusive" <?=$value('price_mode','inclusive')==='inclusive'?'selected':''?>>รวม VAT แล้ว แยกภาษีโดยไม่บวกซ้ำ</option><option value="exclusive" <?=$value('price_mode')==='exclusive'?'selected':''?>>ยังไม่รวม VAT บวกภาษีเพิ่ม</option></select></label><?php field('rate','อัตรา VAT (%)','text',$_SERVER['REQUEST_METHOD']==='POST'?post('rate'):number_format(($current['rate_bps']??700)/100,2,'.',''));field('starts_on','วันที่เริ่มใช้อัตรา','date',$_SERVER['REQUEST_METHOD']==='POST'?post('starts_on'):($current['starts_on']??date('Y-m-d')));field('ends_on','วันที่สิ้นสุดอัตรา','date',$_SERVER['REQUEST_METHOD']==='POST'?post('ends_on'):($current['ends_on']??''),false); ?><label class="checkbox"><input type="checkbox" name="shipping_taxable" <?=($_SERVER['REQUEST_METHOD']==='POST'?isset($_POST['shipping_taxable']):$settings['shipping_taxable'])?'checked':''?>> ค่าจัดส่งและค่าบริการ COD อยู่ภายใต้ VAT ตามนโยบายบัญชีที่ยืนยันแล้ว</label><label class="checkbox"><input type="checkbox" name="invoice_enabled" <?=($_SERVER['REQUEST_METHOD']==='POST'?isset($_POST['invoice_enabled']):$settings['invoice_enabled'])?'checked':''?>> อนุญาตออกใบกำกับภาษีเมื่อข้อมูลตามกฎหมายครบ</label><label class="checkbox"><input type="checkbox" name="legal_confirm" value="1"> ยืนยันสิทธิ์จด VAT ข้อมูลจริง อัตราและหลักเกณฑ์ภาษีโดยผู้รับผิดชอบของร้านแล้ว</label><button>บันทึกภาษี</button></form><p>สินค้ายกเว้นภาษีกำหนดได้ที่เมนูข้อมูลสินค้าสองภาษา / ภาษี</p><?php admin_footer(); ?>
